from collections import Counter

class Solution:
    def minSetSize(self, arr: list[int]) -> int:
        counts = sorted(Counter(arr).values(), reverse=True)
        removed = 0
        half = len(arr) // 2
        for i, c in enumerate(counts):
            removed += c
            if removed >= half:
                return i + 1
        return len(counts)

